'use client';

import Link from 'next/link';
import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { APP_CONFIG } from '@/lib/config';
import ThemeToggle from './ThemeToggle';
import LanguageToggle from './LanguageToggle';
import { useLanguage } from './LanguageProvider';
import { useTheme } from './ThemeProvider';

type NavKey = 'home' | 'about' | 'career' | 'portfolio' | 'contact';
const NAV_ITEMS: NavKey[] = ['home', 'about', 'career', 'portfolio', 'contact'];

export default function Navbar() {
  const { t } = useLanguage();
  const { resolvedTheme } = useTheme();
  const [activeSection, setActiveSection] = useState<NavKey>('home');
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);

      const sections = NAV_ITEMS.map((id) => document.getElementById(id));
      const scrollPos = window.scrollY + 100;

      for (let i = sections.length - 1; i >= 0; i--) {
        const section = sections[i];
        if (section && section.offsetTop <= scrollPos) {
          setActiveSection(NAV_ITEMS[i]);
          break;
        }
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const isDark = resolvedTheme === 'dark';

  return (
    <motion.nav
      className="fixed top-0 w-full z-50 transition-all duration-300 backdrop-blur-xl border-b"
      style={{
        backgroundColor: scrolled
          ? isDark
            ? 'rgba(2, 6, 23, 0.7)'
            : 'rgba(255, 255, 255, 0.7)'
          : 'transparent',
        borderBottomColor: scrolled
          ? isDark
            ? 'rgba(255, 255, 255, 0.06)'
            : 'rgba(0, 0, 0, 0.1)'
          : 'transparent',
      }}
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
    >
      <div className="container mx-auto px-4 h-16 flex items-center justify-between">
        <Link href="/" className="text-xl font-bold gradient-text">
          {APP_CONFIG.name}
        </Link>

        <div className="hidden md:flex gap-1">
          {NAV_ITEMS.map((item) => (
            <Link
              key={item}
              href={`#${item}`}
              className={`relative px-4 py-2 text-sm font-medium rounded-full transition-all duration-300 ${
                activeSection === item
                  ? 'text-white'
                  : isDark
                    ? 'text-gray-400 hover:text-white'
                    : 'text-gray-500 hover:text-gray-900'
              }`}
            >
              {activeSection === item && (
                <motion.span
                  layoutId="nav-pill"
                  className="absolute inset-0 rounded-full bg-blue-600/90 -z-10"
                  transition={{ type: 'spring', stiffness: 380, damping: 30 }}
                />
              )}
              {t.nav[item as keyof typeof t.nav]}
            </Link>
          ))}
        </div>

        <div className="flex items-center gap-3">
          <LanguageToggle />
          <ThemeToggle />
        </div>
      </div>
    </motion.nav>
  );
}
